  "root": "root",
  "components": [
    {
      "id": "root",
      "type": "Column",
      "children": [
        "title",
        "intro",
        "calendar",
        "sections_list",
        "choices_row"
      ]
    },
    {
      "id": "title",
      "type": "Text",
      "variant": "heading",
      "text": {
        "$bind": "/title"
      }
    },
    {
      "id": "intro",
      "type": "Text",
      "variant": "body",
      "text": {
        "$bind": "/intro"
      }
    },
    {
      "id": "calendar",
      "type": "Calendar",
      "title": "Select a date",
      "value": {
        "$bind": "/today"
      },
      "onSelect": {
        "action": "request_data"
      }
    },
    {
      "id": "sections_list",
      "type": "Timeline",
      "title": "Planning Considerations",
      "events": {
        "$bind": "/section_events"
      }
    },
    {
      "id": "choices_row",
      "type": "Row",
      "justify": "spaceBetween",
      "children": [
        "btn_early",
        "btn_mid",
        "btn_late"
      ]
    },
    {
      "id": "btn_early",
      "type": "Button",
      "label": "Early Month (1-10)",
      "onPress": {
        "action": "request_data"
      }
    },
    {
      "id": "btn_mid",
      "type": "Button",
      "label": "Mid Month (11-20)",
      "onPress": {
        "action": "request_data"
      }
    },
    {
      "id": "btn_late",
      "type": "Button",
      "label": "Late Month (21-31)",
      "onPress": {
        "action": "request_data"
      }
    }
  ]
}

payload.raw:
{
  "title": "Mom's Birthday Reminder Selection",
  "intro": "Select a date to set your annual reminder. Consider the following breakdown of the month to help you choose the best time for planning and celebration.",
  "sections": [
    {
      "heading": "Early Month (1st - 10th)",
      "points": [
        "Ideal for early planning",
        "Avoids end-of-month financial stress",
        "Ensures gifts arrive before the actual day"
      ]
    },
    {
      "heading": "Mid Month (11th - 20th)",
      "points": [
        "Balanced timing",
        "Good for weekend celebration planning",
        "Avoids beginning-of-month busy periods"
      ]
    },
    {
      "heading": "Late Month (21st - 31st)",
      "points": [
        "Best if you prefer to celebrate closer to month-end",
        "Allows for post-payday gift shopping",
        "Good for planning long-weekend festivities"
      ]
    }
  ],
  "choices": [
    {"id": "early", "label": "Early Month (1-10)"},
    {"id": "mid", "label": "Mid Month (11-20)"},
    {"id": "late", "label": "Late Month (21-31)"}
  ]
}

